//! Replicates C++ `std::ostream << float` default formatting
//! (defaultfloat, precision 6 — same as printf("%g", (double)v)).

const PRECISION: i32 = 6;

pub fn format_f32(v: f32) -> String {
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf" } else { "inf" }.to_string();
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0" } else { "0" }.to_string();
    }

    let neg = v < 0.0;
    let a = (v as f64).abs();

    // Round to PRECISION significant decimal digits via Rust's correctly
    // rounded scientific formatting, e.g. "1.23457e7".
    let sci = format!("{:.*e}", (PRECISION - 1) as usize, a);
    let epos = sci.find('e').unwrap();
    let x: i32 = sci[epos + 1..].parse().unwrap();
    let digits: String = sci[..epos].chars().filter(|c| *c != '.').collect();
    debug_assert_eq!(digits.len(), PRECISION as usize);

    let body = if x < -4 || x >= PRECISION {
        // Scientific notation: d.ddddd, strip trailing zeros and '.',
        // then 'e', sign, at least 2 exponent digits.
        let mut m = String::new();
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            m.push('.');
            m.push_str(frac);
        }
        format!("{}e{:+03}", m, x)
    } else if x >= 0 {
        // Fixed notation, value >= 1.
        let split = x as usize + 1;
        let int_part = &digits[..split];
        let frac = digits[split..].trim_end_matches('0');
        if frac.is_empty() {
            int_part.to_string()
        } else {
            format!("{}.{}", int_part, frac)
        }
    } else {
        // Fixed notation, 0.00...dddddd. The leading digit is nonzero,
        // so the fraction is never entirely stripped away.
        let zeros = (-x - 1) as usize;
        let mut frac = String::with_capacity(zeros + digits.len());
        for _ in 0..zeros {
            frac.push('0');
        }
        frac.push_str(&digits);
        let frac = frac.trim_end_matches('0');
        format!("0.{}", frac)
    };

    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

