// xorshift PRNG, deterministic
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        (x >> 32) as u32
    }
}

fn main() {
    let mut bits_list: Vec<u32> = vec![
        0x00000001, 0x0000000A, 0x007FFFFF, 0x00800000, 0x80000001,
        0x807FFFFF, 0x00000000, 0x80000000, 0x7F800000, 0xFF800000,
        0x7FC00000, 0x4B400001, 0x4B3FFFFF, 0x3F800000, 0x3DCCCCCD,
    ];
    let mut rng = Rng(0x123456789abcdef);
    for _ in 0..50000 {
        bits_list.push(rng.next());
    }
    // extra: patterns dense around powers of 10 and rounding boundaries
    for i in 0..10000u32 {
        bits_list.push(0x2EDBE6FFu32.wrapping_add(i)); // near 1e-10
        bits_list.push(0x49742400u32.wrapping_add(i)); // near 1e6
    }

    // bits file for the C oracle
    let hex: String = bits_list
        .iter()
        .map(|b| format!("{:08x}\n", b))
        .collect();
    std::fs::write("/tmp/fmt_test/bits.txt", hex).unwrap();

    // our output
    let mine: String = bits_list
        .iter()
        .map(|&b| fmt::format_f32(f32::from_bits(b)) + "\n")
        .collect();
    std::fs::write("/tmp/fmt_test/mine.txt", mine).unwrap();
    println!("{} values", bits_list.len());
}

