fn g6(x: f32) -> String {
    // emulate C %g with precision 6 via formatting: Rust {:e}/{:} differ; do it manually
    // Use C printf through libc? Simpler: implement %g by rounding to 6 sig digits.
    if x == 0.0 { return if x.is_sign_negative() { "-0".into() } else { "0".into() }; }
    if x.is_nan() { return "nan".into() }
    if x.is_infinite() { return if x < 0.0 { "-inf".into() } else { "inf".into() }; }
    // round to 6 significant digits
    let exp10 = x.abs().log10().floor() as i32;
    // adjust: after rounding, exponent may bump
    let mut e = exp10;
    let scaled = x / 10f32.powi(e);
    let mut r = (scaled * 1e5).round() / 1e5; // 6 sig digits
    if r.abs() >= 10.0 { r /= 10.0; e += 1; }
    if e < -4 || e >= 6 {
        // scientific: d.ddddd e±XX, strip trailing zeros in mantissa
        let mut m = format!("{:.5}", r.abs());
        while m.contains('.') && m.ends_with('0') { m.pop(); }
        if m.ends_with('.') { m.pop(); }
        format!("{}{}e{}{:02}", if x<0.0{"-"}else{""}, m, if e<0{"-"}else{"+"}, e.abs())
    } else {
        // fixed with 6-e-1 digits after the point, strip trailing zeros
        let prec = (5 - e).max(0) as usize;
        let mut s = format!("{:.*}", prec, x);
        if s.contains('.') {
            while s.ends_with('0') { s.pop(); }
            if s.ends_with('.') { s.pop(); }
        }
        s
    }
}
fn main() {
    for ratio_s in ["0.1","0.3","0.7","0.333333"] {
        let r1: f32 = "0.1".parse().unwrap();
        let r2: f32 = "0.9".parse().unwrap();
        let ratio: f32 = ratio_s.parse().unwrap();
        let a = r1 * (1.0f32 - ratio) + r2 * ratio;
        let b = r1 + (r2 - r1) * ratio;
        println!("ratio={}: A bits={:08x} g6={}  | B bits={:08x} g6={}  | equal_bits={} equal_g6={}",
            ratio_s, a.to_bits(), g6(a), b.to_bits(), g6(b), a.to_bits()==b.to_bits(), g6(a)==g6(b));
    }
}
EOF
