/// Mirrors the two exception types `std::stof` can throw; in the reference
/// program both are uncaught and abort with the same "terminate called ..."
/// stderr pattern (only the exception name differs).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StofError {
    /// No conversion could be performed (`std::invalid_argument`).
    InvalidArgument,
    /// The value is out of `float` range (`std::out_of_range`).
    OutOfRange,
