/// One blend channel, following the reference binary's exact instruction
/// schedule (see ColorConverter::blend disassembly):
///   s  = subss(1.0, ratio)        // dst = 1.0 const
///   t1 = mulss(c1, s)             // dst = c1
///   t2 = mulss(c2, ratio)         // dst = c2
///   g/b: addss(t1, t2)  (dst = t1);  r: addss(t2, t1)  (dst = t2)
/// The schedule only matters for NaN results (sign/payload propagation).
fn blend_channel(c1: f32, c2: f32, ratio: f32, r_order: bool) -> f32 {
    let s = sse(1.0, ratio, 1.0 - ratio);
    let t1 = sse(c1, s, c1 * s);
    let t2 = sse(c2, ratio, c2 * ratio);
    if r_order {
        sse(t2, t1, t2 + t1)
    } else {
        sse(t1, t2, t1 + t2)
    }
}

